plist.dict:
Label {{LAUNCHD_LABEL}} ProgramArguments
{{PYTHON}} -u {{AGENT_PATH}} --host {{HOST}} --port {{PORT}}{{EXTRA_PLIST_ARGS}}
WorkingDirectory {{INSTALL_DIR}} RunAtLoad
KeepAlive
ThrottleInterval 10 ProcessType Background Umask 63 StandardOutPath {{LOG_DIR}}/agent.log StandardErrorPath {{LOG_DIR}}/agent.log {{USERNAME_BLOCK}}
